const raw = $input.first().json.output;

// Clean JSON wrapper
const cleaned = raw.replace(/^```json\n/, '').replace(/\n```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  console.error('JSON Parse Error:', err.message);
  // Fallback parsing
  parsed = {
    action: 'chat',
    targets: [],
    subject: 'General Query',
    context: raw,
    urgency: 'medium',
    customMessage: '',
    timeReference: '',
    meetingDuration: '1 hour'
  };
}

// Extract and validate
const actionType = parsed.action || 'chat';
const targets = Array.isArray(parsed.targets) ? parsed.targets : [];
const subject = parsed.subject || 'Team Communication';
const context = parsed.context || '';
const urgency = parsed.urgency || 'medium';
const customMessage = parsed.customMessage || '';
const timeReference = parsed.timeReference || '';
const meetingDuration = parsed.meetingDuration || '1 hour';

// Create output items for each target
const items = targets.length > 0 ? targets.map((target, index) => ({
  json: {
    id: index + 1,
    department: target.department || '',
    designation: target.designation || '',
    actionType,
    subject,
    context,
    urgency,
    customMessage,
    timeReference,
    meetingDuration,
    originalInput: $('When chat message received').first().json.chatInput
  }
})) : [{
  json: {
    id: 1,
    department: '',
    designation: '',
    actionType,
    subject,
    context,
    urgency,
    customMessage,
    timeReference,
    meetingDuration,
    originalInput: $('When chat message received').first().json.chatInput
  }
}];

return items;

