const raw = $input.first().json.output;

// Clean and parse JSON
const cleaned = raw.replace(/^```json\n/, '').replace(/\n```$/, '').trim();

let meetingData;
try {
  meetingData = JSON.parse(cleaned);
} catch (err) {
  console.error('Meeting JSON Parse Error:', err);
  // Fallback with proper date handling
  const now = new Date();
  const startTime = new Date(now.getTime() + 60 * 60 * 1000); // 1 hour from now
  const endTime = new Date(startTime.getTime() + 60 * 60 * 1000); // 1 hour duration

  meetingData = {
    title: 'Team Meeting',
    description: 'Scheduled team meeting',
    startTime: startTime.toISOString(),
    endTime: endTime.toISOString(),
    attendees: ['team@company.com'],
    location: 'Google Meet'
  };
}

return { json: meetingData };

const results = $input.all();
const teamMembers = [];

for (const result of results) {
  if (result.json.document && result.json.document.fields) {
    const fields = result.json.document.fields;
    teamMembers.push({
      name: fields.name?.stringValue || 'N/A',
      email: fields.email?.stringValue || 'N/A', 
      department: fields.department?.stringValue || 'N/A',
      designation: fields.designation?.stringValue || 'N/A',
      phone: fields.phone?.stringValue || 'N/A'
    });
  }
}

const response = {
  action: 'query_complete',
  totalMembers: teamMembers.length,
  members: teamMembers,
  message: teamMembers.length > 0 
    ? `Found ${teamMembers.length} team member(s)` 
    : 'No team members found matching the criteria',
  query: {
    department: $('Parse AI Response').item.json.department,
    designation: $('Parse AI Response').item.json.designation,
    context: $('Parse AI Response').item.json.context
  }
};

return [{ json: response }];

// Determine response type and format final output
const actionType = $('Parse AI Response').item.json.actionType;
let response;

switch(actionType) {
  case 'email':
    const emailResult = $('Send Email').first()?.json;
    response = {
      action: 'email_sent',
      success: true,
      message: 'Email sent successfully!',
      details: {
        subject: $('Parse Email JSON').first().json.subject,
        recipient: $('Parse Email JSON').first().json.recipient,
        emailId: emailResult?.id || 'N/A'
      }
    };
    break;

  case 'schedule':
    const meetingResult = $('Create Calendar Event').first()?.json;
    response = {
      action: 'meeting_scheduled', 
      success: true,
      message: 'Meeting scheduled successfully!',
      details: {
        title: $('Parse Meeting JSON').first().json.title,
        startTime: $('Parse Meeting JSON').first().json.startTime,
        meetLink: meetingResult?.hangoutLink || meetingResult?.htmlLink || 'Will be generated',
        eventId: meetingResult?.id || 'N/A'
      }
    };
    break;

  case 'query':
    const queryResult = $('Format Query Response').first().json;
    response = queryResult;
    break;

  case 'chat':
    const chatResult = $('Chat Assistant').first().json;
    response = {
      action: 'chat_response',
      message: chatResult.output || 'Hello! How can I help you with team management today?'
    };
    break;

  default:
    response = {
      action: 'unknown',
      message: 'I\'m not sure how to help with that. Try asking about team members, sending emails, or scheduling meetings!'
    };
}

return [{ json: response }];
